import React, { useState } from "react";

// Feature extraction: JS port of the Python extractor used for training
// (27 lexical/structural URL features, no network calls).

const SHORTENERS = new Set([
  "bit.ly", "goo.gl", "tinyurl.com", "ow.ly", "t.co", "is.gd",
  "buff.ly", "adf.ly", "bit.do", "mcaf.ee", "rebrand.ly", "cutt.ly",
  "shorte.st", "s.id", "tiny.cc", "clck.ru", "lnkd.in",
]);

const SUSPICIOUS_KEYWORDS = [
  "login", "verify", "update", "secure", "account", "signin",
  "bank", "confirm", "password", "webscr", "ebayisapi", "wp-admin",
  "suspend", "authorize", "billing", "invoice", "alert",
];

const IP_PATTERN = /^(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/;

function ensureScheme(url) {
  url = url.trim();
  if (!/^[a-zA-Z][a-zA-Z0-9+.-]*:\/\//.test(url)) url = "http://" + url;
  return url;
}

function safeParseUrl(url) {
  try { return new URL(url); } catch (e) { return null; }
}

function isValidUrl(raw) {
  if (!raw || !raw.trim()) return false;
  const parsed = safeParseUrl(ensureScheme(raw));
  if (!parsed) return false;
  const host = parsed.hostname;
  if (!host) return false;
  if (host.indexOf(".") === -1 && !IP_PATTERN.test(host)) return false;
  if (/[^a-zA-Z0-9\-.:[\]]/.test(host)) return false;
  return true;
}

function shannonEntropy(s) {
  if (!s) return 0.0;
  const counts = {};
  for (const c of s) counts[c] = (counts[c] || 0) + 1;
  let entropy = 0;
  for (const c in counts) {
    const p = counts[c] / s.length;
    entropy -= p * Math.log2(p);
  }
  return entropy;
}

function countChar(s, ch) {
  let n = 0;
  for (const c of s) if (c === ch) n++;
  return n;
}

function extractFeatures(rawUrl) {
  const url = ensureScheme(rawUrl);
  const parsed = safeParseUrl(url);
  const host = (parsed.hostname || "").toLowerCase();
  const path = parsed.pathname || "";
  const full = url.toLowerCase();
  const labels = host ? host.split(".") : [];
  const subdomainCount = Math.max(labels.length - 2, 0);
  const numDigits = (full.match(/[0-9]/g) || []).length;

  const f = {};
  f.url_length = url.length;
  f.host_length = host.length;
  f.path_length = path.length;
  f.num_dots = countChar(full, ".");
  f.num_hyphens = countChar(full, "-");
  f.num_underscores = countChar(full, "_");
  f.num_slashes = countChar(full, "/");
  f.num_at_symbols = countChar(full, "@");
  f.num_question_marks = countChar(full, "?");
  f.num_equal_signs = countChar(full, "=");
  f.num_ampersands = countChar(full, "&");
  f.num_percent = countChar(full, "%");
  f.num_digits = numDigits;
  f.digit_ratio = full.length ? numDigits / full.length : 0;
  f.num_subdomains = subdomainCount;
  f.has_ip_address = IP_PATTERN.test(host) ? 1 : 0;
  f.uses_https = parsed.protocol === "https:" ? 1 : 0;
  const registeredDomain = labels.length >= 2 ? labels.slice(-2).join(".") : host;
  f.is_shortened = SHORTENERS.has(registeredDomain) ? 1 : 0;
  f.has_suspicious_keyword = SUSPICIOUS_KEYWORDS.some((k) => full.includes(k)) ? 1 : 0;
  f.has_port = parsed.port ? 1 : 0;
  f.double_slash_in_path = path.includes("//") ? 1 : 0;
  f.brand_like_subdomain = subdomainCount >= 3 ? 1 : 0;
  f.url_entropy = Math.round(shannonEntropy(full) * 1000) / 1000;
  f.hostname_entropy = Math.round(shannonEntropy(host) * 1000) / 1000;
  f.has_www_prefix = labels[0] === "www" ? 1 : 0;
  f.path_depth = path.split("/").filter(Boolean).length;
  f.tld_length = labels.length ? labels[labels.length - 1].length : 0;
  return f;
}

function explainSuspicious(f) {
  const reasons = [];
  if (f.has_ip_address) reasons.push("The link uses a raw IP address instead of a website name.");
  if (f.is_shortened) reasons.push("The link uses a link-shortening service that hides the real destination.");
  if (f.has_suspicious_keyword) reasons.push("The link contains words often used in phishing, such as login, verify or secure.");
  if (f.num_subdomains >= 3) reasons.push("The link has an unusually high number of subdomains.");
  if (f.url_length > 75) reasons.push("The link is unusually long.");
  if (f.num_at_symbols > 0) reasons.push("The link contains an @ symbol, which can hide the real destination.");
  if (f.num_hyphens >= 4) reasons.push("The link contains many hyphens.");
  if (f.url_entropy > 4.3) reasons.push("The link looks randomly generated.");
  return reasons;
}

