function predictTree(tree, x) {
  let i = 0;
  while (tree.feature[i] !== -2) {
    i = x[tree.feature[i]] <= tree.threshold[i] ? tree.left[i] : tree.right[i];
  }
  return tree.value[i];
}

function predictProba(featuresObj) {
  const x = FOREST.feature_names.map((name) => featuresObj[name]);
  let sum = 0;
  for (const tree of FOREST.trees) sum += predictTree(tree, x);
  return sum / FOREST.trees.length;
}

function riskLevel(confidence, label) {
  if (label === "legitimate") return "Low";
  if (confidence >= 0.85) return "High";
  if (confidence >= 0.6) return "Medium";
  return "Low";
}

const EXAMPLES = [
  { label: "Wikipedia", url: "https://www.wikipedia.org" },
  { label: "Link with IP address", url: "http://192.168.4.12/wp-login/verify" },
  { label: "Lookalike domain", url: "http://secure-paypal-update.account-verify.info/confirm" },
  { label: "Shortened link", url: "http://bit.ly/3xKq9zT" },
];

const FEATURE_LABELS = {
  url_length: "URL length (characters)",
  host_length: "Domain length",
  path_length: "Path length",
  num_dots: "Number of dots",
  num_hyphens: "Number of hyphens",
  num_underscores: "Number of underscores",
  num_slashes: "Number of slashes",
  num_at_symbols: "Number of @ symbols",
  num_question_marks: "Number of ? marks",
  num_equal_signs: "Number of = signs",
  num_ampersands: "Number of & symbols",
  num_percent: "Number of % symbols",
  num_digits: "Number of digits",
  digit_ratio: "Share of characters that are digits",
  num_subdomains: "Number of subdomains",
  has_ip_address: "Uses an IP address",
  uses_https: "Uses HTTPS",
  is_shortened: "Link shortener",
  has_suspicious_keyword: "Suspicious keyword present",
  has_port: "Custom port in URL",
  double_slash_in_path: "Double slash in path",
  brand_like_subdomain: "Many subdomains (3+)",
  url_entropy: "URL randomness score",
  hostname_entropy: "Domain randomness score",
  has_www_prefix: "Starts with www",
  path_depth: "Path depth (folders)",
  tld_length: "Domain ending length",
};

const YES_NO = new Set([
  "has_ip_address", "uses_https", "is_shortened", "has_suspicious_keyword",
  "has_port", "double_slash_in_path", "brand_like_subdomain", "has_www_prefix",
]);

function formatValue(name, val) {
  if (YES_NO.has(name)) return val ? "Yes" : "No";
  return String(Math.round(val * 100) / 100);
}

const STEPS = [
  "Check the link format",
  "Measure 27 features of the link",
  "Ask 50 decision trees to vote",
  "Show the result",
];

export default function PhishGuard() {
  const [urlInput, setUrlInput] = useState("");
  const [result, setResult] = useState(null);
  const [error, setError] = useState("");
  const [scanning, setScanning] = useState(false);
  const [showDetails, setShowDetails] = useState(false);

  function runScan(rawUrl) {
    setError("");
    setResult(null);
    setShowDetails(false);

    const trimmed = (rawUrl || "").trim();
    if (!trimmed) {
      setError("Please type or paste a link first.");
      return;
    }
    if (!isValidUrl(trimmed)) {
      setError("That doesn't look like a valid link. Try something like https://example.com");
      return;
    }

    setScanning(true);
    setTimeout(() => {
      const features = extractFeatures(trimmed);
      const pPhishing = predictProba(features);
      const label = pPhishing >= 0.5 ? "phishing" : "legitimate";
      const confidence = label === "phishing" ? pPhishing : 1 - pPhishing;

      setResult({
        url: trimmed,
        label,
        confidence: Math.round(confidence * 100),
        risk: riskLevel(confidence, label),
        reasons: label === "phishing" ? explainSuspicious(features) : [],
        features,
      });
      setScanning(false);
    }, 200);
  }

  const isPhishing = result && result.label === "phishing";

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 font-sans">
      <header className="bg-white border-b border-slate-200">
        <div className="mx-auto max-w-3xl px-6 py-4">
          <div className="text-xl font-bold text-slate-900">PhishGuard</div>
          <div className="text-sm text-slate-600">Phishing website checker</div>
        </div>
      </header>

      <main className="mx-auto max-w-3xl px-6 py-10">
        <h1 className="text-3xl font-bold text-slate-900">Is this link safe?</h1>
        <p className="mt-2 text-base text-slate-600 leading-relaxed">
          Paste a website link below. The checker runs in your browser and tells
          you whether the link looks like phishing or a legitimate website.
        </p>

        <div className="mt-8 rounded-xl border border-slate-200 bg-white p-6 shadow-sm">
          <label htmlFor="url" className="block text-sm font-semibold text-slate-800">
            Website link
          </label>
          <form
            onSubmit={(e) => {
              e.preventDefault();
              runScan(urlInput);
            }}
            className="mt-2 flex flex-col gap-3 sm:flex-row"
          >
            <input
              id="url"
              type="text"
              value={urlInput}
              onChange={(e) => setUrlInput(e.target.value)}
              placeholder="https://example.com"
              spellCheck={false}
              className="flex-1 rounded-lg border border-slate-300 bg-white px-4 py-3 text-base text-slate-900 placeholder-slate-400 focus:border-blue-600 focus:outline-none focus:ring-2 focus:ring-blue-200"
            />
            <button
              type="submit"
              disabled={scanning}
              className="rounded-lg bg-blue-700 px-6 py-3 text-base font-semibold text-white hover:bg-blue-800 disabled:opacity-60"
            >
              {scanning ? "Checking…" : "Check link"}
            </button>
          </form>

          <div className="mt-4 flex flex-wrap items-center gap-2">
            <span className="text-sm text-slate-600">Try an example:</span>
            {EXAMPLES.map((ex) => (
              <button
                key={ex.url}
                onClick={() => {
                  setUrlInput(ex.url);
                  runScan(ex.url);
                }}
                className="rounded-full border border-slate-300 bg-white px-3 py-1.5 text-sm text-slate-700 hover:bg-slate-100"
              >
                {ex.label}
              </button>
            ))}
          </div>
        </div>

        {error && (
          <div className="mt-6 rounded-lg border border-amber-300 bg-amber-50 px-4 py-3 text-base text-amber-900">
            {error}
          </div>
        )}

        {result && (
          <section className="mt-8">
            <div
              className={
                "rounded-xl border-2 p-6 " +
                (isPhishing ? "border-red-300 bg-red-50" : "border-green-300 bg-green-50")
              }
            >
              <div className="text-sm font-semibold text-slate-700">Result</div>
              <div
                className={
                  "mt-1 text-3xl font-bold " +
                  (isPhishing ? "text-red-800" : "text-green-800")
                }
              >
                {isPhishing ? "Likely phishing" : "Looks legitimate"}
              </div>
              <p className="mt-2 text-base text-slate-800">
                {isPhishing
                  ? "Do not enter passwords or personal details on this website."
                  : "No strong phishing signs were found in this link."}
              </p>
              <div className="mt-4 break-all rounded-lg bg-white/70 px-3 py-2 text-sm text-slate-700">
                {result.url}
              </div>
            </div>

            <div className="mt-4 grid grid-cols-2 gap-4">
              <div className="rounded-xl border border-slate-200 bg-white p-5">
                <div className="text-sm text-slate-600">Confidence</div>
                <div className="mt-1 text-2xl font-bold text-slate-900">{result.confidence}%</div>
              </div>
              <div className="rounded-xl border border-slate-200 bg-white p-5">
                <div className="text-sm text-slate-600">Risk level</div>
                <div
                  className={
                    "mt-1 text-2xl font-bold " +
                    (result.risk === "High"
                      ? "text-red-700"
                      : result.risk === "Medium"
                      ? "text-amber-700"
                      : "text-green-700")
                  }
                >
                  {result.risk}
                </div>
              </div>
            </div>

            {result.reasons.length > 0 && (
              <div className="mt-4 rounded-xl border border-slate-200 bg-white p-6">
                <h2 className="text-lg font-semibold text-slate-900">Warning signs in this link</h2>
                <ul className="mt-3 list-disc space-y-2 pl-5 text-base text-slate-800">
                  {result.reasons.map((r, i) => (
                    <li key={i}>{r}</li>
                  ))}
                </ul>
              </div>
            )}

            <div className="mt-4 rounded-xl border border-slate-200 bg-white p-6">
              <button
                onClick={() => setShowDetails(!showDetails)}
                className="flex w-full items-center justify-between text-left text-lg font-semibold text-slate-900"
              >
                Technical details
                <span className="text-sm font-medium text-blue-700">
                  {showDetails ? "Hide" : "Show"}
                </span>
              </button>
              {showDetails && (
                <table className="mt-4 w-full text-base">
                  <tbody>
                    {Object.entries(result.features).map(([name, val]) => (
                      <tr key={name} className="border-t border-slate-200">
                        <td className="py-2 pr-4 text-slate-700">{FEATURE_LABELS[name] || name}</td>
                        <td className="py-2 text-right font-semibold text-slate-900">
                          {formatValue(name, val)}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              )}
            </div>
          </section>
        )}

        <section className="mt-12">
          <h2 className="text-lg font-semibold text-slate-900">How it works</h2>
          <ol className="mt-3 list-decimal space-y-1 pl-5 text-base text-slate-700">
            {STEPS.map((s) => (
              <li key={s}>{s}</li>
            ))}
          </ol>
        </section>
      </main>

      <footer className="border-t border-slate-200 bg-white">
        <p className="mx-auto max-w-3xl px-6 py-5 text-sm text-slate-600">
          This is a student prototype. Results are predictions, not guarantees,
          so don't rely on them as your only security check.
        </p>
      </footer>
    </div>
  );
}
